tool_input.command:
cat > /tmp/test_calendar.mjs << 'EOF'
import fs from 'fs';
import path from 'path';
import { interpret } from './machtzev/generator/entity.mjs';

const spec = fs.readFileSync('./machtzev/generator/specs-ds/calendar.txt', 'utf8');
const lines = spec.split('\n');

// Find the meeting entity line
const entityLine = lines.find(l => l.includes('ישות פגישה'));
console.log('Entity line:', entityLine);

const result = interpret(entityLine);
console.log('\nParsed entity:');
console.log('- Name:', result.name);
console.log('- Fields:');
result.fields.forEach(f => {
  console.log(`  - ${f.label}: type=${f.type}, formula=${f.formula || 'none'}`);
});

// Verify the computed field
const hoursField = result.fields.find(f => f.label === 'משך בשעות');
if (hoursField) {
  console.log('\n✓ Found computed field "משך בשעות"');
  console.log(`  Formula: ${hoursField.formula}`);
  if (hoursField.formula === 'משך בדקות / 60') {
    console.log('  ✓ Formula is correct!');
  }
} else {
  console.log('\n✗ Computed field "משך בשעות" not found');
}
EOF
node /tmp/test_calendar.mjs
